    out.domainType = wire.domainType;
    out.setCombatUnit(wire.combatUnit());
    out.setCivilianUnit(wire.civilianUnit());
    out.setCanDefend(wire.canDefend());
    out.setCanAttack(wire.canAttack());
    out.setCanAttackRanged(wire.canAttackRanged());
    out.setCanAttackWithMove(wire.canAttackWithMove());
    out.setMoveAfterAttacking(wire.moveAfterAttacking());
    out.setFreeAttackMoves(wire.freeAttackMoves());
    out.setRangedSupportFire(wire.rangedSupportFire());
    out.range = static_cast<i32>(wire.range);
