    out.setEverFortifyable(wire.everFortifyable());
    out.setInCombat(wire.inCombat());
    out.setRequiresLeadership(wire.requiresLeadership());
    out.flankAttackModifier = static_cast<i32>(wire.flankAttackModifier);
    out.rangedAttackModifier = static_cast<i32>(wire.rangedAttackModifier);
    out.setIgnoreZoc(wire.ignoreZoc());
