    out.setCanPillage(wire.canPillage());
    out.pillageHealAmount = static_cast<i32>(wire.pillageHealAmount);
    out.setCanRepairFleet(wire.canRepairFleet());
    out.setCannotHeal(wire.cannotHeal());
    out.actualHealRate = static_cast<i32>(wire.actualHealRate);
    out.unitClassType = static_cast<i32>(wire.unitClassType);
    out.baseMovesEmbarked = static_cast<i32>(wire.baseMovesEmbarked);
    out.setCanMoveImpassable(wire.canMoveImpassable());
    out.setCanMoveAllTerrain(wire.canMoveAllTerrain());
    out.setCanCrossOceans(wire.canCrossOceans());
