    for (int index = 0; index < 4; ++index) out.terrainImpassable[index] = wire.terrainImpassable[index];
    out.setRivalTerritory(wire.rivalTerritory());
    out.setTradeUnit(wire.tradeUnit());
    out.setEnemyRoute(wire.enemyRoute());
    out.setNoDefensiveBonus(wire.noDefensiveBonus());
