    out.movementCountRangeFirst = wire.movementCountRangeFirst;
    out.movementCountRangeCount = wire.movementCountRangeCount;
    out.mapLayer = 0;
    out.airSweepCombatModifier = 0;
    out.numAttacksMadeThisTurn = 0;
    out.cargoCount = 0;
    out.airInterceptRange = 0;
    out.multiAttackBonus = 0;
    out.splashDamage = 0;
    out.cityAttackPlunderModifier = 0;
    out.damageTakenLastTurn = 0;
    out.interceptionCombatModifier = 0;
    out.extraMoveDiscount = 0;
    out.sameTileHeal = 0;
    out.adjacentTileHeal = 0;
    out.extraFriendlyHeal = 0;
    out.extraEnemyHeal = 0;
    out.extraNeutralHeal = 0;
    out.flatHealRate = 0;
    out.auraRangeChange = 0;
    out.auraEffectChange = 0;
    out.adjacentCityDefenseMod = 0;
    out.damageAoeFortified = 0;
    out.aoeDamageOnMove = 0;
    out.tileDamageIfNotMoved = 0;
    out.extraXpOnKill = 0;
    out.goldenAgeValueFromKills = 0;
    out.aoeHealOnPillage = 0;
    out.aoeDamageOnPillage = 0;
    out.xpFromPillaging = 0;
    out.attackWoundedModifier = 0;
    out.attackFullyHealedModifier = 0;
    out.attackBelow50HealthModifier = 0;
    out.forcedDamageValue = 0;
    out.changeDamageValue = 0;
    out.damageTakenMod = 0;
    out.damageReductionCityAssault = 0;
    out.moraleBreakChance = 0;
    out.interceptionDefenseDamageModifier = 0;
    out.landAirDefenseValue = 0;
    out.yieldFromKills = 0;
    out.yieldFromBarbarianKills = 0;
    out.alwaysHostileCount = 0;
    out.interceptChance = 0;
    out.leaderUnitType = -1;
    out.numExoticGoods = 0;
