    out.nearbyUnitClassBonusRange = 0;
    out.nearbyUnitClassBonus = 0;
    out.nearbyCityCombatMod = 0;
    out.nearbyFriendlyCityCombatMod = 0;
    out.nearbyEnemyCityCombatMod = 0;
    out.combatBonusImprovement = -1;
    out.nearbyImprovementBonusRange = 0;
    out.nearbyImprovementCombatBonus = 0;
    out.giveCombatMod = 0;
    out.nearbyUnitPromotionsRange = 0;
    out.giveDefenseMod = 0;
