    if (true) {
        void* destination = 0; u32 length = 0;
        if (!VoxRlMultiplyU32(static_cast<u32>(resultAssignmentDamage.size()), sizeof(ResultAssignmentDamageRecord), length) || !writer.BeginSection(static_cast<u16>(VOX_RL_SECTION_RESULT_ASSIGNMENT_DAMAGE), static_cast<u32>(resultAssignmentDamage.size()), length, &destination)) return false;
        if (length != 0) VoxRlBuilderCopy(destination, &resultAssignmentDamage[0], length);
    }
    if (true) {
        void* destination = 0; u32 length = 0;
        if (!VoxRlMultiplyU32(static_cast<u32>(resultAssignmentHealing.size()), sizeof(ResultAssignmentHealingRecord), length) || !writer.BeginSection(static_cast<u16>(VOX_RL_SECTION_RESULT_ASSIGNMENT_HEALING), static_cast<u32>(resultAssignmentHealing.size()), length, &destination)) return false;
        if (length != 0) VoxRlBuilderCopy(destination, &resultAssignmentHealing[0], length);
    }
