inline bool AppendReplayHeaderRecordAssignmentRange(VoxRlReplayPlanData* data, const std::vector<ReplayAssignmentRecord>& rows)
{
    return data != 0 && AppendReplayHeaderRecordAssignmentRange(&data->replayHeader, data, rows);
}

// Appends rows to replayUnusableUnits and assigns the replayHeader range.
inline bool AppendReplayHeaderRecordUnusableUnitRange(VoxRlReplayPlanData* data, const std::vector<ReplayUnusableUnitRecord>& rows)
{
    return data != 0 && AppendReplayHeaderRecordUnusableUnitRange(&data->replayHeader, data, rows);
}

inline bool VoxRlValidateReplayPlanData(const VoxRlReplayPlanData& data)
{
    if (true && !VoxRlBuilderRangeFits(data.replayHeader.assignmentRangeFirst, data.replayHeader.assignmentRangeCount, data.replayAssignments.size())) return false;
    if (true && !VoxRlBuilderRangeFits(data.replayHeader.unusableUnitRangeFirst, data.replayHeader.unusableUnitRangeCount, data.replayUnusableUnits.size())) return false;
    if (!VoxRlBuilderSizeFitsU32(data.replayAssignments.size())) return false;
    for (size_t index = 0; index < data.replayAssignments.size(); ++index) {
        if (!VoxRlBuilderRangeFits(data.replayAssignments[index].unitDamageRangeFirst, data.replayAssignments[index].unitDamageRangeCount, data.replayAssignmentDamage.size())) return false;
    }
    for (size_t index = 0; index < data.replayAssignments.size(); ++index) {
        if (!VoxRlBuilderRangeFits(data.replayAssignments[index].unitHealingRangeFirst, data.replayAssignments[index].unitHealingRangeCount, data.replayAssignmentHealing.size())) return false;
    }
    if (!VoxRlBuilderSizeFitsU32(data.replayAssignmentDamage.size())) return false;
    if (!VoxRlBuilderSizeFitsU32(data.replayAssignmentHealing.size())) return false;
    if (!VoxRlBuilderSizeFitsU32(data.replayUnusableUnits.size())) return false;
    u32 replayAssignmentsCursor = 0;
    if (true && (data.replayHeader.assignmentRangeFirst != replayAssignmentsCursor || !VoxRlAddU32(replayAssignmentsCursor, data.replayHeader.assignmentRangeCount, replayAssignmentsCursor))) return false;
    if (replayAssignmentsCursor != static_cast<u32>(data.replayAssignments.size())) return false;
    u32 replayUnusableUnitsCursor = 0;
    if (true && (data.replayHeader.unusableUnitRangeFirst != replayUnusableUnitsCursor || !VoxRlAddU32(replayUnusableUnitsCursor, data.replayHeader.unusableUnitRangeCount, replayUnusableUnitsCursor))) return false;
    if (replayUnusableUnitsCursor != static_cast<u32>(data.replayUnusableUnits.size())) return false;
    u32 replayAssignmentDamageCursor = 0;
    for (size_t parentIndex = 0; parentIndex < data.replayAssignments.size(); ++parentIndex) {
        const ReplayAssignmentRecord& parent = data.replayAssignments[parentIndex];
        if (parent.unitDamageRangeFirst != replayAssignmentDamageCursor || !VoxRlAddU32(replayAssignmentDamageCursor, parent.unitDamageRangeCount, replayAssignmentDamageCursor)) return false;
    }
    if (replayAssignmentDamageCursor != static_cast<u32>(data.replayAssignmentDamage.size())) return false;
    u32 replayAssignmentHealingCursor = 0;
    for (size_t parentIndex = 0; parentIndex < data.replayAssignments.size(); ++parentIndex) {
        const ReplayAssignmentRecord& parent = data.replayAssignments[parentIndex];
        if (parent.unitHealingRangeFirst != replayAssignmentHealingCursor || !VoxRlAddU32(replayAssignmentHealingCursor, parent.unitHealingRangeCount, replayAssignmentHealingCursor)) return false;
    }
    if (replayAssignmentHealingCursor != static_cast<u32>(data.replayAssignmentHealing.size())) return false;
    return true;
}

inline void VoxRlReplayPlanData::Clear()
{
    replayHeader = ReplayHeaderRecord();
    replayAssignments.clear();
    replayAssignmentDamage.clear();
    replayAssignmentHealing.clear();
    replayUnusableUnits.clear();
}

inline bool VoxRlReplayPlanData::ByteLength(u32* byteLength) const
{
    if (byteLength == 0 || !VoxRlValidateReplayPlanData(*this)) return false;
    u16 sectionCount = 0;
    if (true) ++sectionCount;
    if (true) ++sectionCount;
    if (true) ++sectionCount;
    if (true) ++sectionCount;
    if (true) ++sectionCount;
    u32 directoryLength = 0; u32 offset = 0;
    if (!VoxRlMultiplyU32(sectionCount, sizeof(VoxRlSectionDirectoryEntry), directoryLength) || !VoxRlAddU32(sizeof(VoxRlImageHeader), directoryLength, offset) || !VoxRlAlignU32(offset, offset)) return false;
    if (true) {
        u32 length = 0;
        if (!VoxRlMultiplyU32(1U, sizeof(ReplayHeaderRecord), length) || !VoxRlAlignU32(offset, offset) || !VoxRlAddU32(offset, length, offset)) return false;
    }
    if (true) {
        u32 length = 0;
        if (!VoxRlMultiplyU32(static_cast<u32>(replayAssignments.size()), sizeof(ReplayAssignmentRecord), length) || !VoxRlAlignU32(offset, offset) || !VoxRlAddU32(offset, length, offset)) return false;
    }
    if (true) {
        u32 length = 0;
        if (!VoxRlMultiplyU32(static_cast<u32>(replayAssignmentDamage.size()), sizeof(ReplayAssignmentDamageRecord), length) || !VoxRlAlignU32(offset, offset) || !VoxRlAddU32(offset, length, offset)) return false;
    }
    if (true) {
        u32 length = 0;
        if (!VoxRlMultiplyU32(static_cast<u32>(replayAssignmentHealing.size()), sizeof(ReplayAssignmentHealingRecord), length) || !VoxRlAlignU32(offset, offset) || !VoxRlAddU32(offset, length, offset)) return false;
    }
    if (true) {
        u32 length = 0;
        if (!VoxRlMultiplyU32(static_cast<u32>(replayUnusableUnits.size()), sizeof(ReplayUnusableUnitRecord), length) || !VoxRlAlignU32(offset, offset) || !VoxRlAddU32(offset, length, offset)) return false;
    }
    if (offset > 1048576U) return false;
    return VoxRlAddU32(sizeof(VoxRlFrameHeader), offset, *byteLength);
}

inline bool VoxRlReplayPlanData::Write(const VoxRlBlockIdentity& identity, void* bytes, u32 capacity, u32* byteLength) const
{
    if (byteLength == 0 || !VoxRlValidateReplayPlanData(*this)) return false;
    u16 sectionCount = 0;
    if (true) ++sectionCount;
    if (true) ++sectionCount;
    if (true) ++sectionCount;
    if (true) ++sectionCount;
    if (true) ++sectionCount;
    VoxRlBlockWriter writer(bytes, capacity);
    if (!writer.Begin(static_cast<u16>(VOX_RL_BLOCK_REPLAY_PLAN), sectionCount, identity.decisionId, identity.session, identity.turn, identity.player, identity.generation, identity.staticGeneration, identity.worldGeneration, identity.campaignGeneration, identity.deltaSequence, identity.flags)) return false;
    if (true) {
        void* destination = 0; u32 length = 0;
        if (!VoxRlMultiplyU32(1U, sizeof(ReplayHeaderRecord), length) || !writer.BeginSection(static_cast<u16>(VOX_RL_SECTION_REPLAY_HEADER), 1U, length, &destination)) return false;
        if (length != 0) VoxRlBuilderCopy(destination, &replayHeader, length);
    }
    if (true) {
        void* destination = 0; u32 length = 0;
        if (!VoxRlMultiplyU32(static_cast<u32>(replayAssignments.size()), sizeof(ReplayAssignmentRecord), length) || !writer.BeginSection(static_cast<u16>(VOX_RL_SECTION_REPLAY_ASSIGNMENTS), static_cast<u32>(replayAssignments.size()), length, &destination)) return false;
        if (length != 0) VoxRlBuilderCopy(destination, &replayAssignments[0], length);
    }
    if (true) {
        void* destination = 0; u32 length = 0;
        if (!VoxRlMultiplyU32(static_cast<u32>(replayAssignmentDamage.size()), sizeof(ReplayAssignmentDamageRecord), length) || !writer.BeginSection(static_cast<u16>(VOX_RL_SECTION_REPLAY_ASSIGNMENT_DAMAGE), static_cast<u32>(replayAssignmentDamage.size()), length, &destination)) return false;
        if (length != 0) VoxRlBuilderCopy(destination, &replayAssignmentDamage[0], length);
    }
    if (true) {
        void* destination = 0; u32 length = 0;
        if (!VoxRlMultiplyU32(static_cast<u32>(replayAssignmentHealing.size()), sizeof(ReplayAssignmentHealingRecord), length) || !writer.BeginSection(static_cast<u16>(VOX_RL_SECTION_REPLAY_ASSIGNMENT_HEALING), static_cast<u32>(replayAssignmentHealing.size()), length, &destination)) return false;
        if (length != 0) VoxRlBuilderCopy(destination, &replayAssignmentHealing[0], length);
    }
    if (true) {
        void* destination = 0; u32 length = 0;
        if (!VoxRlMultiplyU32(static_cast<u32>(replayUnusableUnits.size()), sizeof(ReplayUnusableUnitRecord), length) || !writer.BeginSection(static_cast<u16>(VOX_RL_SECTION_REPLAY_UNUSABLE_UNITS), static_cast<u32>(replayUnusableUnits.size()), length, &destination)) return false;
        if (length != 0) VoxRlBuilderCopy(destination, &replayUnusableUnits[0], length);
    }
    return writer.Finish(byteLength);
}

inline bool VoxRlReplayPlanData::Write(const VoxRlBlockIdentity& identity, VoxRlOwnedBlockStorage* storage, u32* byteLength) const
{
    u32 required = 0;
    if (storage == 0 || !ByteLength(&required) || !storage->Allocate(required)) return false;
    return Write(identity, storage->MutableBytes(), storage->ByteLength(), byteLength);
}

inline bool VoxRlReplayPlanData::Write(const VoxRlBlockIdentity& identity, VoxRlOwnedBlockStorage& storage, u32& byteLength) const
{
    return Write(identity, &storage, &byteLength);
}

